package edu.riara.edp.week09;
import javafx.application.Application;import javafx.concurrent.Task;import javafx.scene.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Stage;
public class ProgressDemo extends Application {public void start(Stage s){ProgressBar bar=new ProgressBar(0);Label status=new Label("Ready");Button run=new Button("Start"),cancel=new Button("Cancel");run.setOnAction(e->{Task<Void> task=new Task<>(){protected Void call()throws Exception{for(int i=1;i<=20;i++){if(isCancelled())break;Thread.sleep(150);updateProgress(i,20);updateMessage(i+"/20");}return null;}};bar.progressProperty().unbind();bar.progressProperty().bind(task.progressProperty());status.textProperty().unbind();status.textProperty().bind(task.messageProperty());run.setDisable(true);cancel.setOnAction(ev->task.cancel());task.setOnSucceeded(ev->run.setDisable(false));task.setOnCancelled(ev->{run.setDisable(false);status.textProperty().unbind();status.setText("Cancelled");});task.setOnFailed(ev->run.setDisable(false));Thread t=new Thread(task);t.setDaemon(true);t.start();});s.setScene(new Scene(new VBox(12,bar,status,new HBox(10,run,cancel)),440,190));s.show();}public static void main(String[]a){launch(a);}}